"use client";

import { motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Switch } from "@/components/motion/switch";

import { formatPercent, formatWhole } from "../lib/format";
import { paddedExtent } from "../lib/plot";
import { usePointCursor } from "../lib/use-point-cursor";
import { BlockFrame } from "../parts/block-frame";
import { RollingText } from "../parts/rolling-text";
import {
  FLAT_UNDER,
  growthOf,
  type Region,
  REGIONS,
  type ScaleKey,
  type SortKey,
  TOTAL,
  WEEKS,
  weekLabel,
} from "./small-multiples/data";
import { Panel } from "./small-multiples/panel";

const SORTS: { value: SortKey; label: string }[] = [
  { value: "latest", label: "Latest" },
  { value: "growth", label: "Growth" },
  { value: "name", label: "Name" },
];

const SCALES: { value: ScaleKey; label: string }[] = [
  { value: "independent", label: "Own scale" },
  { value: "shared", label: "Shared scale" },
];

const ORDER = {
  latest: (a, b) => (b.weeks.at(-1) ?? 0) - (a.weeks.at(-1) ?? 0),
  growth: (a, b) => growthOf(b.weeks) - growthOf(a.weeks),
  name: (a, b) => a.name.localeCompare(b.name),
} satisfies Record<SortKey, (a: Region, b: Region) => number>;

/**
 * Weekly bookings at eight clinics as a grid of small charts read as one:
 * one crosshair moves through every panel at once. Sort the panels, switch
 * between each panel's own scale and one shared scale, and dim the clinics
 * whose trend stayed flat. The grid is one tab stop; arrows move a week.
 */
export function SmallMultiples({ className }: { className?: string }) {
  const titleId = useId();
  const dimId = useId();
  const reduceMotion = useReducedMotion();
  const [sort, setSort] = useState<SortKey>("latest");
  const [scale, setScale] = useState<ScaleKey>("independent");
  const [dimFlat, setDimFlat] = useState(true);
  const [hovered, setHovered] = useState<string | null>(null);
  const cursor = usePointCursor(WEEKS, 4);
  const { index } = cursor;
  const {
    tabIndex,
    onKeyDown,
    onBlur,
    onPointerDown,
    onPointerMove,
    onPointerLeave,
  } = cursor.plotProps;

  const sorted = [...REGIONS].sort(ORDER[sort]);
  const shared = paddedExtent(REGIONS.map((region) => region.weeks));
  const week = index ?? WEEKS - 1;
  const weekTotal = TOTAL[week] ?? 0;
  const readout = `${index === null ? "Latest week" : "Week of"} ${weekLabel(week)}: ${formatWhole(weekTotal)} bookings across all clinics. ${sorted
    .map((region) => `${region.name} ${formatWhole(region.weeks[week] ?? 0)}`)
    .join(", ")}.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <div>
          <h2 id={titleId} className="text-base font-semibold">
            Bookings by clinic
          </h2>
          <p className="text-sm text-muted-foreground">
            Weekly bookings, {weekLabel(0)} to {weekLabel(WEEKS - 1)}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <SegmentedControl
            aria-label="Sort clinics by"
            options={SORTS}
            value={sort}
            onValueChange={setSort}
          />
          <SegmentedControl
            aria-label="Scale"
            options={SCALES}
            value={scale}
            onValueChange={setScale}
          />
          <label
            htmlFor={dimId}
            className="flex min-h-11 cursor-pointer items-center gap-2 text-sm text-muted-foreground sm:min-h-9"
          >
            Dim flat trends
            <Switch id={dimId} checked={dimFlat} onCheckedChange={setDimFlat} />
          </label>
        </div>
      </header>

      <div className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1 px-5 py-3">
        <p className="flex items-baseline gap-2 text-sm">
          <span className="font-medium">
            {index === null ? "Latest week" : "Week of"} {weekLabel(week)}
          </span>
          <span className="text-muted-foreground">
            Total{" "}
            <RollingText
              text={formatWhole(weekTotal)}
              className="font-medium text-foreground"
            />
          </span>
        </p>
        <p
          aria-hidden="true"
          className="flex items-center gap-3 text-xs text-muted-foreground"
        >
          <span className="flex items-center gap-1.5">
            <span className="h-0.5 w-3 rounded-full bg-chart-1" /> Clinic
          </span>
          <span className="flex items-center gap-1.5">
            <span className="w-3 border-t border-dashed border-muted-foreground" />{" "}
            All clinics, scaled to fit
          </span>
        </p>
      </div>
      <p aria-live="polite" className="sr-only">
        {index === null ? "" : readout}
      </p>

      <div
        tabIndex={tabIndex}
        onKeyDown={onKeyDown}
        onBlur={onBlur}
        role="application"
        aria-roledescription="chart grid"
        aria-label="Weekly bookings at eight clinics. Use the arrow keys to move a week in every chart."
        className="border-t border-border outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
      >
        <ul className="grid grid-cols-1 gap-px bg-border @md:grid-cols-2 @2xl:grid-cols-4">
          {sorted.map((region) => {
            const flat = Math.abs(growthOf(region.weeks)) < FLAT_UNDER;
            return (
              <motion.li
                key={region.id}
                layout={!reduceMotion}
                transition={{
                  type: "spring",
                  stiffness: 300,
                  damping: 35,
                  mass: 1,
                }}
                className="bg-card"
              >
                <Panel
                  region={region}
                  extent={
                    scale === "shared" ? shared : paddedExtent([region.weeks])
                  }
                  total={TOTAL}
                  index={index}
                  dimmed={
                    (dimFlat && flat) ||
                    (hovered !== null && hovered !== region.id)
                  }
                  pointer={{ onPointerDown, onPointerMove, onPointerLeave }}
                  onHover={(on) => setHovered(on ? region.id : null)}
                />
              </motion.li>
            );
          })}
        </ul>
      </div>
      <p className="px-5 py-3 text-xs text-muted-foreground">
        Flat means bookings moved less than {formatPercent(FLAT_UNDER)} over the
        half year.
      </p>
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import { formatDay, sampleDate } from "../../lib/format";
import { makeSeries, percentChange } from "../../lib/plot";

/** How many weeks each clinic's line covers. */
export const WEEKS = 26;

/** One clinic's weekly bookings, oldest first, and its chart colour. */
export interface Region {
  id: string;
  name: string;
  weeks: number[];
  /** The text colour class the line, area and dot take through `currentColor`. */
  hue: string;
}

const HUES = [
  "text-chart-1",
  "text-chart-2",
  "text-chart-3",
  "text-chart-4",
  "text-chart-5",
];

const SEEDS: [string, string, number, number, number][] = [
  ["harbour", "Harbour Street", 412, 538, 38],
  ["mill", "Mill Lane", 296, 301, 26],
  ["northgate", "Northgate", 188, 264, 20],
  ["orchard", "Orchard Road", 352, 318, 30],
  ["quay", "The Quay", 141, 212, 16],
  ["riverside", "Riverside", 236, 239, 22],
  ["elm", "Elm Park", 98, 157, 12],
  ["castle", "Castle Hill", 274, 241, 24],
];

/** Every clinic with its line. Whole bookings, so the figures read like counts. */
export const REGIONS: Region[] = SEEDS.map(
  ([id, name, start, end, noise], index) => ({
    id,
    name,
    weeks: makeSeries(index * 13 + 5, WEEKS, start, end, noise).map(Math.round),
    hue: HUES[index % HUES.length] ?? "text-chart-1",
  }),
);

/** Every clinic added up, week by week. */
export const TOTAL = Array.from({ length: WEEKS }, (_, week) =>
  REGIONS.reduce((sum, region) => sum + (region.weeks[week] ?? 0), 0),
);

/** The growth of a line from its first week to its last, in percent. */
export const growthOf = (weeks: number[]) =>
  percentChange(weeks[0] ?? 0, weeks[weeks.length - 1] ?? 0);

/** A trend that moved less than this share over the half year counts as flat. */
export const FLAT_UNDER = 4;

/** The Monday a week starts on, written short, such as "Oct 26". */
export const weekLabel = (week: number) =>
  formatDay(sampleDate((WEEKS - 1 - week) * 7 + 5));

/** The orders a person can sort the panels by. */
export type SortKey = "latest" | "growth" | "name";
/** Whether each panel fits its own range or every panel shares one. */
export type ScaleKey = "independent" | "shared";

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import type { PointerEvent } from "react";

import { cn } from "@/lib/utils";

import { formatWhole } from "../../lib/format";
import { areaPath, linePath, paddedExtent, toX, toY } from "../../lib/plot";
import { Delta } from "../../parts/delta";
import { RollingText } from "../../parts/rolling-text";
import { growthOf, type Region } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for one small chart. */
export interface PanelProps {
  region: Region;
  extent: [number, number];
  /** The company total, drawn faintly behind the line and scaled to fit the panel. */
  total: number[];
  /** The week every panel inspects, or null for none. */
  index: number | null;
  dimmed: boolean;
  pointer: {
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
  };
  onHover: (hovered: boolean) => void;
}

// Critically damped: the line and its axis settle on the new scale with no wobble.
const MORPH: Transition = {
  type: "spring",
  stiffness: 240,
  damping: 31,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/**
 * One clinic: its name, the latest week, growth over the half year, and a
 * line with its area and end dot. The inspected week shows a dot and the
 * figure for that week in place of the latest. Decorative to screen readers:
 * the grid's readout says the same figures.
 */
export function Panel({
  region,
  extent,
  total,
  index,
  dimmed,
  pointer,
  onHover,
}: PanelProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : MORPH;
  const { weeks } = region;
  const last = weeks.length - 1;
  const shown = index ?? last;
  const value = weeks[shown] ?? 0;
  const ghostExtent = paddedExtent([total], 0.12);

  return (
    <div
      aria-hidden="true"
      onPointerEnter={() => onHover(true)}
      onPointerLeave={() => onHover(false)}
      className={cn(
        "flex flex-col gap-2 bg-card p-4 motion-safe:transition-opacity motion-safe:duration-200",
        dimmed && "opacity-40",
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <span className="truncate text-sm font-medium">{region.name}</span>
        <RollingText
          text={formatWhole(value)}
          className="text-sm font-semibold"
        />
      </div>
      <Delta value={growthOf(weeks)} className="self-start" />
      <div className="flex gap-2">
        <div
          {...pointer}
          className={cn(
            "relative h-20 min-w-0 flex-1 cursor-crosshair touch-pan-y",
            region.hue,
          )}
        >
          <svg
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            className="absolute inset-0 size-full overflow-visible"
          >
            <path
              d={linePath(total, ghostExtent, 50)}
              fill="none"
              strokeWidth="1"
              strokeDasharray="3 3"
              vectorEffect="non-scaling-stroke"
              className="stroke-muted-foreground/40"
            />
            <motion.path
              initial={false}
              animate={{ d: areaPath(weeks, extent, 50) }}
              transition={transition}
              fill="currentColor"
              className="opacity-15"
            />
            <motion.path
              initial={false}
              animate={{ d: linePath(weeks, extent, 50) }}
              transition={transition}
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
          {index !== null ? (
            <span
              className="left-(--x) absolute inset-y-0 w-px bg-foreground/30"
              style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--x": `${toX(index, weeks.length)}%` } as VarStyle
              }
            />
          ) : null}
          <motion.span
            initial={false}
            animate={{
              left: `${toX(shown, weeks.length)}%`,
              top: `${toY(value, extent)}%`,
            }}
            transition={index === null ? transition : INSTANT}
            className="absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-card bg-current"
          />
        </div>
        <div className="flex w-9 shrink-0 flex-col justify-between text-right text-xs text-muted-foreground">
          <RollingText text={formatWhole(extent[1])} className="justify-end" />
          <RollingText text={formatWhole(extent[0])} className="justify-end" />
        </div>
      </div>
    </div>
  );
}

import { ArrowDownIcon, ArrowUpIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { formatPercent } from "../lib/format";
import { STATUS_TEXT } from "../lib/status";

/** Props for a change figure. */
export interface DeltaProps {
  /** The percent change. */
  value: number;
  /** Set when a fall is the good direction, such as no-shows or waiting time. */
  lowerIsBetter?: boolean;
  className?: string;
}

/**
 * A percent change with an arrow. The arrow and the spoken word carry the
 * direction, and the colour says only whether the change is good.
 */
export function Delta({ value, lowerIsBetter = false, className }: DeltaProps) {
  const flat = Math.abs(value) < 0.05;
  const up = value > 0;
  const good = flat ? null : up !== lowerIsBetter;
  const Arrow = up ? ArrowUpIcon : ArrowDownIcon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium tabular-nums",
        good === null ? "text-muted-foreground" : STATUS_TEXT[good ? "good" : "bad"],
        className,
      )}
    >
      {flat ? null : <Arrow aria-hidden="true" className="size-3" />}
      <span className="sr-only">{flat ? "No change" : up ? "Up" : "Down"}</span>
      {formatPercent(value)}
    </span>
  );
}

